import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';

// The app icon (track B « Le point », 2026-10-24) is generated by
// tool/app_icon/make_app_icon.py. These checks follow the store rules, not
// the script: App Store Connect refuses an iOS icon with an alpha channel,
// and Android 13 themed icons need a <monochrome> layer.

const _appIconSet = 'ios/Runner/Assets.xcassets/AppIcon.appiconset';
const _res = 'android/app/src/main/res';

/// Width, height and colour type, read from a PNG's IHDR chunk.
({int width, int height, int colourType}) _pngHeader(String path) {
  final bytes = File(path).readAsBytesSync();
  expect(bytes.sublist(0, 8), [
    137,
    80,
    78,
    71,
    13,
    10,
    26,
    10,
  ], reason: '$path is not a PNG');
  final data = ByteData.sublistView(Uint8List.fromList(bytes));
  return (
    width: data.getUint32(16),
    height: data.getUint32(20),
    colourType: bytes[25],
  );
}

void main() {
  group('iOS', () {
    final contents =
        jsonDecode(File('$_appIconSet/Contents.json').readAsStringSync())
            as Map<String, dynamic>;
    final images = (contents['images'] as List).cast<Map<String, dynamic>>();

    test('one 1024 icon per appearance: default, dark and tinted', () {
      final appearances = images
          .map(
            (i) =>
                ((i['appearances'] as List?)?.first as Map?)?['value'] ??
                'default',
          )
          .toSet();
      expect(appearances, {'default', 'dark', 'tinted'});
      for (final image in images) {
        expect(image['size'], '1024x1024');
      }
    });

    test(
      'every listed file exists, is 1024 × 1024 and has no alpha channel',
      () {
        for (final image in images) {
          final path = '$_appIconSet/${image['filename']}';
          expect(File(path).existsSync(), isTrue, reason: '$path is missing');
          final header = _pngHeader(path);
          expect((header.width, header.height), (1024, 1024), reason: path);
          // 2 = truecolour; 4 and 6 carry alpha, which the App Store refuses.
          expect(
            header.colourType,
            2,
            reason: '$path must be RGB without alpha',
          );
        }
      },
    );

    test('no stale icon left in the set', () {
      final listed = images.map((i) => i['filename']).toSet();
      final onDisk = Directory(_appIconSet)
          .listSync()
          .map((f) => f.uri.pathSegments.last)
          .where((name) => name.endsWith('.png'))
          .toSet();
      expect(onDisk, listed);
    });
  });

  group('Android', () {
    test(
      'the adaptive icon has a background, a foreground and a monochrome layer',
      () {
        for (final name in ['ic_launcher.xml', 'ic_launcher_round.xml']) {
          final xml = File('$_res/mipmap-anydpi-v26/$name').readAsStringSync();
          expect(xml, contains('<background'), reason: name);
          expect(xml, contains('<foreground'), reason: name);
          expect(xml, contains('<monochrome'), reason: name);
        }
      },
    );

    test('the foreground is a 108 dp vector, not a bitmap', () {
      final xml = File(
        '$_res/drawable/ic_launcher_foreground.xml',
      ).readAsStringSync();
      expect(xml, contains('<vector'));
      expect(xml, contains('android:viewportWidth="108"'));
      expect(xml, contains('android:pathData'));
    });

    test('the manifest declares the round icon', () {
      final manifest = File(
        'android/app/src/main/AndroidManifest.xml',
      ).readAsStringSync();
      expect(
        manifest,
        contains('android:roundIcon="@mipmap/ic_launcher_round"'),
      );
    });

    test('legacy launcher icons have the size of their density', () {
      const sizes = {
        'mdpi': 48,
        'hdpi': 72,
        'xhdpi': 96,
        'xxhdpi': 144,
        'xxxhdpi': 192,
      };
      sizes.forEach((density, size) {
        for (final name in ['ic_launcher.png', 'ic_launcher_round.png']) {
          final header = _pngHeader('$_res/mipmap-$density/$name');
          expect(
            (header.width, header.height),
            (size, size),
            reason: '$density/$name',
          );
        }
      });
    });
  });
}
